/// The row's fields that hold text.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum RowText {
    /// The run's arrivals profile, its knob's text (STRIMS_SIM_ARRIVALS,
    /// SIM_ARRIVALS); left out for one with every viewer from the start
    /// (strims-sim) or without arrivals or departures (the ppspp sim).
    Arrivals,
    /// The clock skew the run's clocks had (STRIMS_SIM_CLOCK_SKEW,
    /// SIM_CLOCK_SKEW): its knob's text.
    ///
    /// None is written as an empty field.
    ClockSkew,
    /// The run's departures profile, its knob's text (STRIMS_SIM_DEPART,
    /// SIM_DEPART); left out without departures.
    Depart,
    /// The test's check's failure, empty when it passed.
    ///
    /// None is written as an empty field.
    Failure,
    /// A media swarm's encoder (MediaSpec); left out without media.
    Media,
    /// A digest of the honest viewers' reads as 16 hex digits, which a change
    /// that moves only readers changes and the trace may not.
    ///
    /// strims-sim: The first 16 hex digits of a SHA-256 over each honest
    /// viewer's swarm, host and frames read, then each frame's seq and lag
    /// (Report::reads_hash).
    ReadsHash,
    /// The scenario's name.
    Scenario,
    /// A media swarm's signing policy (MediaSpec); left out without media.
    Sign,
    /// The sweep test the job ran (strims-sim's tests/scenarios.rs name).
    Test,
    /// The run's trace digest as 16 hex digits: what the nodes sent, which a
    /// rerun must reproduce.
    ///
    /// strims-sim: The first 16 hex digits of the trace hash over the run's
    /// events and a few of its reads.
    Trace,
}

impl RowText {
    /// The name, as strims-sim writes it.
    pub(crate) fn name(self) -> &'static str {
        match self {
            RowText::Arrivals => "arrivals",
            RowText::ClockSkew => "clock_skew",
            RowText::Depart => "depart",
            RowText::Failure => "failure",
            RowText::Media => "media",
            RowText::ReadsHash => "reads_hash",
            RowText::Scenario => "scenario",
            RowText::Sign => "sign",
            RowText::Test => "test",
            RowText::Trace => "trace",
        }
    }
}

impl sealed::Sealed for RowText {}

impl Key for RowText {
    fn name(self) -> &'static str {
        RowText::name(self)
    }
}

/// The row's fields that hold a list of integers.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum RowInts {
    /// Per BUCKET (30 s) of the first swarm's stream time from its start, the
    /// median lag in ms of the frames its viewers read (Report::lag_buckets).
    ///
    /// Unit: ms.
    BucketP50Ms,
    /// Per BUCKET (30 s) of the first swarm's stream time from its start, the
    /// p99 lag in ms of the frames its viewers read (Report::lag_buckets).
    ///
    /// Unit: ms.
    BucketP99Ms,
    /// With clock skew, every host's (node's) clock offset in signed ms, by
    /// host index.
    ///
    /// Unit: ms. None is written as an empty field.
    ClockOffsetsMs,
}

impl RowInts {
    /// The name, as strims-sim writes it.
    pub(crate) fn name(self) -> &'static str {
        match self {
            RowInts::BucketP50Ms => "bucket_p50_ms",
            RowInts::BucketP99Ms => "bucket_p99_ms",
            RowInts::ClockOffsetsMs => "clock_offsets_ms",
        }
    }
}

impl sealed::Sealed for RowInts {}

impl Key for RowInts {
    fn name(self) -> &'static str {
        RowInts::name(self)
    }
}

/// The row's fields that hold a list of numbers.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum RowNums {
    /// Per BUCKET (30 s) of the first swarm's stream from its start, the median
    /// of the upload meter's capacity ÷ the uplink over the samples of each
    /// population's viewers (`meter_{pop}_p{p}`'s), as `meter_bucket_seeds` is
    /// the seeds'.
    MeterBucketPop(u16),
    /// **meter readings**: the upload meter's capacity, the relay busy-time
    /// reading admission and shedding take (`PushStats::upload_capacity`,
    /// `MeterSample::capacity`), ÷ the host's uplink: the seed's quantiles
    /// `meter_seed_p*`, the populations' `meter_accepting_p*`,
    /// `meter_delivering_p*` and `meter_others_p*`, its median per bucket over
    /// the seeds' samples (`meter_bucket_seeds`) and the populations'
    /// (`meter_bucket_accepting`, `meter_bucket_delivering`,
    /// `meter_bucket_others`), and how it tracked changes
    /// (`off_{change}_{role}`).
    MeterBucketSeeds,
    /// How the upload meter tracked each change of the host's available upload
    /// (a step of its uplink's rate, a competing upload's start or stop) while
    /// a swarm streamed, over the hosts of role `role` (`seeds`, the swarms'
    /// seeds; `accepting` and `delivering`, the first swarm's honest viewers of
    /// each population, `meter_{pop}_p{p}`'s): the share of the meter's samples
    /// from the change to the next that read more than TRACK_BAND off the
    /// uplink, its median and its largest over the drops (`off_drop_seeds`,
    /// ...) and over the rises (`off_rise_seeds`, ...) (Report::tracking); left
    /// out where the role's hosts had no change.
    OffChangeRole(u16),
    /// The p10, p50 and p90 in ms of the seeds' meters' queueing delay while a
    /// swarm streams, over the samples that had one
    /// (Report::queue_delay_deciles).
    ///
    /// Unit: ms.
    QueueDelaySeedsMs,
}

impl RowNums {
    /// The name, as strims-sim writes it.
    pub(crate) fn name(self) -> &'static str {
        match self {
            RowNums::MeterBucketPop(i) => at(&ROWNUMS_METER_BUCKET_POP, i),
            RowNums::MeterBucketSeeds => "meter_bucket_seeds",
            RowNums::OffChangeRole(i) => at(&ROWNUMS_OFF_CHANGE_ROLE, i),
            RowNums::QueueDelaySeedsMs => "queue_delay_seeds_ms",
        }
    }

    /// `meter_bucket_{pop}`'s name of `pop`: a panic for values
    /// `fields.toml` doesn't give strims-sim.
    pub(crate) fn meter_bucket_pop(pop: impl Display) -> RowNums {
        RowNums::MeterBucketPop(of(
            &ROWNUMS_METER_BUCKET_POP,
            format_args!("meter_bucket_{pop}"),
        ))
    }

    /// `off_{change}_{role}`'s name of `change`, `role`: a panic for values
    /// `fields.toml` doesn't give strims-sim.
    pub(crate) fn off_change_role(change: impl Display, role: impl Display) -> RowNums {
        RowNums::OffChangeRole(of(
            &ROWNUMS_OFF_CHANGE_ROLE,
            format_args!("off_{change}_{role}"),
        ))
    }
}

impl sealed::Sealed for RowNums {}

impl Key for RowNums {
    fn name(self) -> &'static str {
        RowNums::name(self)
    }
}

