/// The keys of `series_meta.json` that hold an integer.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum MetaInt {
    /// The first swarm's seed: its host in strims-sim, its node (0) in the
    /// ppspp sim.
    Seed,
    /// The first swarm's stream count, at least 1: the streams of the parents
    /// table and of the logs run from 0 below it, whether or not a table has
    /// rows of each.
    ///
    /// strims-sim: Scenario swarm 0's `SwarmOptions::stream_count`; left out
    /// without a swarm.
    Streams,
    /// The stream's rate, in bytes per second.
    Rate,
    /// The stream's chunk size, in bytes.
    Chunk,
    /// The size of the frames the series counts, in bytes: strims-sim's frame
    /// (FRAME_LEN; a media swarm's chunk), the ppspp sim's chunk.
    Frame,
    /// The stream's length in seconds; the seconds after it are the run's tail.
    ///
    /// Unit: s.
    Secs,
    /// The viewers' uplinks, summed.
    ViewerUp,
    /// The number of seconds of the series: the seconds table's rows.
    Seconds,
    /// The number of viewers: the viewers table's rows.
    Viewers,
    /// The width of the bins and node_bins tables' bins, in ms
    /// (STRIMS_SIM_BIN_MS, SIM_BIN_MS).
    ///
    /// Unit: ms.
    BinMs,
    /// The forecast samples the nodes' caps left out.
    ForecastsLost,
    /// The parent changes the logs' caps left out.
    ParentsLost,
    /// With the request logs on, the held log's records the caps left out.
    HeldLost,
    /// With the request logs on, the HAVE log's records the caps left out.
    HavesLost,
    /// With the request logs on, the request log's records the caps left out:
    /// requests, each with its rivals.
    AsksLost,
    /// With it too, the seed log's decisions and sends its caps left out are
    /// `seed_log_lost`.
    SeedLogLost,
}

impl MetaInt {
    /// The name, as strims-sim writes it.
    pub(crate) fn name(self) -> &'static str {
        match self {
            MetaInt::Seed => "seed",
            MetaInt::Streams => "streams",
            MetaInt::Rate => "rate",
            MetaInt::Chunk => "chunk",
            MetaInt::Frame => "frame",
            MetaInt::Secs => "secs",
            MetaInt::ViewerUp => "viewer_up",
            MetaInt::Seconds => "seconds",
            MetaInt::Viewers => "viewers",
            MetaInt::BinMs => "bin_ms",
            MetaInt::ForecastsLost => "forecasts_lost",
            MetaInt::ParentsLost => "parents_lost",
            MetaInt::HeldLost => "held_lost",
            MetaInt::HavesLost => "haves_lost",
            MetaInt::AsksLost => "asks_lost",
            MetaInt::SeedLogLost => "seed_log_lost",
        }
    }
}

