    /// The `forecast` table's columns: a row per sample of a node's forecast
    /// log (`strims_ppspp::LagForecast`): a HAVE's announcement lag.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum Forecast {
        /// the HAVE's arrival
        ///
        /// Unit: ms.
        TMs,
        /// The node whose forecast log sampled the HAVE: its host in
        /// strims-sim, its node in the ppspp sim.
        Node,
        /// The node's number in the viewers table; -1 for one that is no viewer
        /// (the seed, a hostile host).
        Viewer,
        /// the hosts
        Peer,
        /// not a hostile host
        PeerHonest,
        /// The HAVE's chunk's stream.
        Stream,
        /// the chunk
        Seq,
        /// the lag: from our first sight of the chunk's unit to the HAVE
        ///
        /// Unit: ms.
        SampleMs,
        /// the mean of the peer's lag estimate before the sample, -1 before its
        /// first sample
        ///
        /// Unit: ms. None is written as -1.
        MeanMs,
        /// how late a sample still fits that estimate: the later of its
        /// decaying peak and its mean plus two deviations, -1 before its first
        /// sample
        ///
        /// Unit: ms. None is written as -1.
        HorizonMs,
        /// the estimate's so far
        Samples,
        /// its latest sample was recent enough for a candidate
        Fresh,
        /// we asked the peer for lazy HAVEs
        Lazy,
        /// this HAVE set the unit's first sight: the sample is 0
        FirstSight,
        /// the sample's place in the HAVE's run of its stream's bins: a whole
        /// unit's HAVE gives one per chunk, the same lag each
        Run,
        /// our first sight of the unit, `t_ms - sample_ms`
        ///
        /// Unit: ms.
        SeenMs,
        /// when the peer first stored the chunk, in the incarnation it had at
        /// the sample: its runner's held log, `Runner::take_held`, a seed's own
        /// writes included; empty if that incarnation never did
        ///
        /// Unit: ms. None is written as -1.
        HeldMs,
        /// when our channel with the peer opened
        ///
        /// Unit: ms.
        ChannelOpenMs,
        /// it was held after both hosts' incarnations started and after the
        /// channel opened: the HAVE tracked its arrival, not a backlog the
        /// channel's first HAVEs announce
        Live,
    }

