    /// The `arrivals` table's columns: a row per chunk a node stored, from its
    /// held log (`strims_ppspp::Held`).
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum Arrivals {
        /// when it first held it: the `forecast` table's `held_ms` is this
        /// row's, in the incarnation the sample's peer had
        ///
        /// Unit: ms.
        TMs,
        /// the host
        Node,
        /// The host's number in the viewers table; -1 for one that is no viewer
        /// (the seed, a hostile host).
        ///
        /// None is written as -1.
        Viewer,
        /// the chunk
        Seq,
        /// `own`: published, or no data message named it, so an unattributed
        /// store too; `push`: pushed by the stream's open parent; `answer`: an
        /// answer to a request of ours, which wins over `push` when the
        /// parent's push answered our request; `other`
        How,
        /// the source's host, -1 for none
        ///
        /// None is written as -1.
        Peer,
        /// the stream's open parent's then, -1 for none
        ///
        /// None is written as -1.
        Parent,
        /// when push first expected it: a HAVE marked it the parent's to push
        ///
        /// Unit: ms.
        ExpectedMs,
        /// when push's deadline, or the parent's going, released it to pull
        ///
        /// Unit: ms.
        ReleasedMs,
        /// our first request for it
        ///
        /// Unit: ms.
        AskedMs,
        /// the requests
        Asks,
        /// the last one's host and time
        ///
        /// None is written as -1.
        LastAskPeer,
        /// the last one's host and time
        ///
        /// Unit: ms.
        LastAskMs,
        /// the source channel's smoothed round trip then
        ///
        /// Unit: ms.
        RttMs,
        /// the host's then: its restarts by the hold, the first 0
        Incarnation,
    }

